import requests

def test_get_health_check_endpoint_returns_500_when_service_unavailable():
    url = "http://localhost:8000/"
    headers = {
        "Accept": "application/json"
    }
    try:
        response = requests.get(url, headers=headers, timeout=30)
    except requests.RequestException as e:
        assert False, f"Request to {url} failed: {e}"

    assert response.status_code == 500, f"Expected status code 500, got {response.status_code}"

    try:
        json_resp = response.json()
    except ValueError:
        assert False, "Response is not valid JSON"

    assert isinstance(json_resp, dict), "Response JSON should be a dictionary"

    # Expect an error message string in the response
    error_message = json_resp.get("message") or json_resp.get("error") or json_resp.get("detail")
    assert error_message is not None, "Expected an error message in the response"

test_get_health_check_endpoint_returns_500_when_service_unavailable()
